INSERT INTO questions (id, subject_id, created_by, type, content, options, correct_answer, difficulty, is_approved, approved_by, approved_at) VALUES
('c74452de-60b3-4e5e-bfc2-d493c4672c63', '34158321-547c-43ef-b6c6-9f5304011cce', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Tế bào nhân thực khác tế bào nhân sơ ở điểm nào sau đây?$q$, $q$[{"id": "A", "text": "Có màng tế bào"}, {"id": "B", "text": "Có nhân hoàn chỉnh với màng nhân"}, {"id": "C", "text": "Có ribosome"}, {"id": "D", "text": "Có DNA"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('8fbf5d1e-efd3-44ff-9ce7-d2f628a119cb', '34158321-547c-43ef-b6c6-9f5304011cce', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Quá trình quang hợp xảy ra chủ yếu ở bào quan nào?$q$, $q$[{"id": "A", "text": "Ti thể"}, {"id": "B", "text": "Ribosome"}, {"id": "C", "text": "Lục lạp"}, {"id": "D", "text": "Không bào"}]$q$::jsonb, $q${"selected": ["C"]}$q$::jsonb, 'thong_hieu', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('c7076e4a-cdd9-495a-b912-fa020ce9ef8e', '34158321-547c-43ef-b6c6-9f5304011cce', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Tế bào sinh dưỡng người (2n=46) trải qua nguyên phân 3 lần liên tiếp. Số tế bào con tạo thành là:$q$, $q$[{"id": "A", "text": "6 tế bào"}, {"id": "B", "text": "8 tế bào"}, {"id": "C", "text": "12 tế bào"}, {"id": "D", "text": "16 tế bào"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('525e35c3-49e6-4497-990d-75c313df8491', '34158321-547c-43ef-b6c6-9f5304011cce', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Tế bào ung thư có khả năng phân chia vô hạn chủ yếu vì lý do nào?$q$, $q$[{"id": "A", "text": "Tế bào ung thư có nhiều ribosome hơn tế bào bình thường"}, {"id": "B", "text": "Gen điều hòa chu kỳ tế bào bị đột biến, mất kiểm soát phân bào"}, {"id": "C", "text": "Tế bào ung thư hấp thụ nhiều chất dinh dưỡng hơn"}, {"id": "D", "text": "DNA của tế bào ung thư tự nhân đôi nhanh hơn"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('6de6b914-2817-4b01-8830-d4bb64302106', '34158321-547c-43ef-b6c6-9f5304011cce', '07c265a0-4938-43fd-a5af-a69509523d8b', 'true_false', $q$Xác định ĐÚNG hoặc SAI với mỗi phát biểu sau về cấu trúc tế bào:$q$, $q$[{"id": "1", "statement": "Màng sinh chất được cấu tạo từ lớp phospholipid kép và protein"}, {"id": "2", "statement": "Ti thể là bào quan thực hiện quá trình quang hợp"}, {"id": "3", "statement": "Ribosome là bào quan không có màng bao bọc"}, {"id": "4", "statement": "Nhân tế bào chứa DNA và điều khiển mọi hoạt động sống của tế bào"}]$q$::jsonb, $q${"answers": {"1": true, "2": false, "3": true, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('2a89ae73-4738-4b99-90b8-4eb24dff81a9', '34158321-547c-43ef-b6c6-9f5304011cce', '07c265a0-4938-43fd-a5af-a69509523d8b', 'true_false', $q$Phân tích các phát biểu sau về nguyên phân và giảm phân:$q$, $q$[{"id": "1", "statement": "Nguyên phân tạo ra tế bào con có bộ NST giống hệt tế bào mẹ (2n)"}, {"id": "2", "statement": "Giảm phân xảy ra ở tế bào sinh dưỡng của cơ thể"}, {"id": "3", "statement": "Sau giảm phân I, mỗi tế bào con có bộ NST đơn bội (n) gồm NST đơn"}, {"id": "4", "statement": "Trao đổi chéo NST xảy ra ở kỳ đầu của giảm phân I"}]$q$::jsonb, $q${"answers": {"1": true, "2": false, "3": false, "4": true}}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('61832a17-d025-4c63-8f81-80fb8e3bc346', '34158321-547c-43ef-b6c6-9f5304011cce', '07c265a0-4938-43fd-a5af-a69509523d8b', 'essay', $q$Phân biệt tế bào nhân sơ và tế bào nhân thực về cấu trúc. Cho ví dụ mỗi loại.$q$, NULL, $q${"sample": "Tế bào nhân sơ (Prokaryote): không có màng nhân, vật chất di truyền (DNA) nằm tự do trong tế bào chất ở vùng nhân (nucleoid), không có các bào quan có màng bao bọc (không có ti thể, lưới nội chất, bộ Golgi). Ví dụ: vi khuẩn E.coli, vi khuẩn lao.\nTế bào nhân thực (Eukaryote): có màng nhân bao bọc DNA, có đầy đủ các bào quan có màng như ti thể, lưới nội chất, bộ Golgi, lục lạp (ở thực vật). Ví dụ: tế bào động vật (hồng cầu, tế bào gan), tế bào thực vật (tế bào lá), tế bào nấm.", "keywords": ["màng nhân", "nhân sơ", "nhân thực", "vi khuẩn", "bào quan", "ti thể", "DNA", "nucleoid"]}$q$::jsonb, 'thong_hieu', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('e13b90d8-4926-42f2-a631-790674f37787', '34158321-547c-43ef-b6c6-9f5304011cce', '07c265a0-4938-43fd-a5af-a69509523d8b', 'essay', $q$Giải thích tại sao người mắc bệnh thiếu men G6PD dễ bị tan máu khi dùng một số loại thuốc như primaquine. Liên hệ với vai trò của enzyme trong hoạt động tế bào.$q$, NULL, $q${"sample": "Men G6PD (glucose-6-phosphate dehydrogenase) có vai trò xúc tác phản ứng tạo NADPH trong chu trình pentose phosphate, giúp duy trì glutathione ở dạng khử (GSH). GSH bảo vệ hồng cầu khỏi bị oxy hóa bởi các gốc tự do. Khi thiếu G6PD, hồng cầu không được bảo vệ, dễ bị phá vỡ (tan máu) khi tiếp xúc với tác nhân oxy hóa như primaquine, dapsone.\nLiên hệ vai trò enzyme: enzyme là chất xúc tác sinh học giúp tăng tốc độ phản ứng hóa học trong tế bào mà không bị tiêu hao. Enzyme có tính đặc hiệu cao với cơ chất. Thiếu một enzyme có thể gây rối loạn toàn bộ chuỗi phản ứng trao đổi chất.", "keywords": ["G6PD", "enzyme", "hồng cầu", "oxy hóa", "glutathione", "tan máu", "NADPH", "xúc tác", "primaquine"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('17f6f3cd-e17c-4123-88b7-23c093e40187', '96e6699b-ac01-48fb-b8f8-add3426b8a84', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Ở người, bộ phận nào của hệ tiêu hóa có chức năng hấp thụ chất dinh dưỡng chủ yếu?$q$, $q$[{"id": "A", "text": "Dạ dày"}, {"id": "B", "text": "Ruột non"}, {"id": "C", "text": "Ruột già"}, {"id": "D", "text": "Thực quản"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('7b76f696-db3e-4b9b-87f3-64bec6d1e4ad', '96e6699b-ac01-48fb-b8f8-add3426b8a84', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Nhịp tim người bình thường khi nghỉ ngơi là bao nhiêu lần/phút?$q$, $q$[{"id": "A", "text": "40 - 50 lần/phút"}, {"id": "B", "text": "60 - 80 lần/phút"}, {"id": "C", "text": "90 - 110 lần/phút"}, {"id": "D", "text": "110 - 130 lần/phút"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('05c6128b-b704-4547-8385-c2e56e71114d', '96e6699b-ac01-48fb-b8f8-add3426b8a84', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Khi nồng độ CO2 trong máu tăng cao, cơ thể người phản ứng như thế nào?$q$, $q$[{"id": "A", "text": "Giảm nhịp thở để tiết kiệm năng lượng"}, {"id": "B", "text": "Tăng nhịp thở để thải CO2 ra ngoài"}, {"id": "C", "text": "Ngừng thở hoàn toàn"}, {"id": "D", "text": "Nhịp thở không thay đổi"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('25f80d21-c2fd-44c9-9407-201d20ecece0', '96e6699b-ac01-48fb-b8f8-add3426b8a84', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Vận động viên marathon thiếu glycogen dự trữ trong cơ và gan. Điều này ảnh hưởng như thế nào đến hiệu suất và cơ thể sẽ bù đắp năng lượng bằng cách nào?$q$, $q$[{"id": "A", "text": "Không ảnh hưởng vì cơ thể còn nhiều nguồn năng lượng khác thay thế"}, {"id": "B", "text": "Cơ thể chuyển sang phân giải lipid và protein, hiệu suất giảm do ATP sinh ra chậm hơn"}, {"id": "C", "text": "Cơ thể ngừng hoạt động hoàn toàn khi hết glycogen"}, {"id": "D", "text": "Nhịp tim tự động giảm để tiết kiệm năng lượng"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('4f76a499-45ae-40f9-9835-88bd7961a008', '96e6699b-ac01-48fb-b8f8-add3426b8a84', '07c265a0-4938-43fd-a5af-a69509523d8b', 'true_false', $q$Xác định ĐÚNG hoặc SAI về hệ tuần hoàn ở các nhóm động vật:$q$, $q$[{"id": "1", "statement": "Cá có hệ tuần hoàn kín với tim 2 ngăn (1 tâm nhĩ và 1 tâm thất)"}, {"id": "2", "statement": "Chim và thú có tim 4 ngăn, hai vòng tuần hoàn hoàn toàn tách biệt"}, {"id": "3", "statement": "Máu trong động mạch luôn giàu O2 hơn máu trong tĩnh mạch"}, {"id": "4", "statement": "Lưỡng cư (ếch nhái) có hệ tuần hoàn kép nhưng chưa hoàn toàn"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": false, "4": true}}$q$::jsonb, 'thong_hieu', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('2543386e-5a31-4030-8339-18394bd11bbb', '96e6699b-ac01-48fb-b8f8-add3426b8a84', '07c265a0-4938-43fd-a5af-a69509523d8b', 'true_false', $q$Phân tích các phát biểu về sinh sản ở thực vật có hoa:$q$, $q$[{"id": "1", "statement": "Sinh sản vô tính ở thực vật không cần sự kết hợp của giao tử đực và cái"}, {"id": "2", "statement": "Hạt phấn mang giao tử đực của thực vật có hoa"}, {"id": "3", "statement": "Quá trình thụ tinh kép là đặc điểm chỉ có ở thực vật Hạt trần (Gymnospermae)"}, {"id": "4", "statement": "Quả được hình thành và phát triển từ bầu nhụy sau khi thụ tinh"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": false, "4": true}}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('2d0f2e32-ad11-4623-af47-5e2adc687b82', '96e6699b-ac01-48fb-b8f8-add3426b8a84', '07c265a0-4938-43fd-a5af-a69509523d8b', 'essay', $q$Trình bày cơ chế điều hòa huyết áp trong cơ thể người. Giải thích tại sao huyết áp cao kéo dài gây nguy hiểm cho sức khỏe.$q$, NULL, $q${"sample": "Huyết áp được điều hòa qua 3 cơ chế chính:\n1. Điều hòa thần kinh: Thụ thể áp lực (baroreceptor) ở xoang động mạch cảnh và cung động mạch chủ nhận biết sự thay đổi huyết áp, gửi tín hiệu về trung khu tuần hoàn ở hành não, từ đó điều chỉnh nhịp tim và sức co bóp tim.\n2. Điều hòa thể dịch: Adrenalin (từ tuyến thượng thận) làm tăng nhịp tim và huyết áp. Aldosterone (từ vỏ thượng thận) giữ Na+ và nước làm tăng thể tích máu. Hệ renin-angiotensin-aldosterone (RAA) điều chỉnh khi huyết áp giảm.\n3. Điều hòa qua thận: Thận lọc máu, điều chỉnh lượng nước và muối thải ra ngoài.\nHuyết áp cao kéo dài gây: tổn thương thành mạch máu, xơ vữa động mạch, phì đại cơ tim dẫn đến suy tim, tăng nguy cơ đột quỵ não, suy thận mạn tính.", "keywords": ["huyết áp", "baroreceptor", "hành não", "renin", "angiotensin", "aldosterone", "adrenalin", "suy tim", "đột quỵ", "thận"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('c65a5c2b-4d6f-4392-88e7-44cfc6b1855b', '96e6699b-ac01-48fb-b8f8-add3426b8a84', '07c265a0-4938-43fd-a5af-a69509523d8b', 'essay', $q$So sánh điều hòa hoạt động cơ thể bằng thần kinh và bằng thể dịch (hormone). Cho ví dụ minh họa.$q$, NULL, $q${"sample": "Điều hòa bằng thần kinh: tốc độ nhanh (mili giây), tác dụng ngắn, chính xác, tác động lên cơ quan đích cụ thể qua sợi thần kinh. Ví dụ: phản xạ rút tay khi chạm vật nóng.\nĐiều hòa bằng thể dịch: tốc độ chậm hơn (giây đến phút), tác dụng kéo dài hơn, phạm vi rộng vì hormone theo máu đến toàn cơ thể. Ví dụ: insulin điều tiết đường huyết sau bữa ăn.\nHai hệ thống phối hợp chặt chẽ: trục hạ đồi - tuyến yên - tuyến đích (ví dụ trục hạ đồi - tuyến yên - tuyến giáp). Thần kinh có thể kích thích hoặc ức chế tuyến nội tiết tiết hormone.", "keywords": ["thần kinh", "thể dịch", "hormone", "phản xạ", "insulin", "hạ đồi", "tuyến yên", "nhanh", "chậm", "phối hợp"]}$q$::jsonb, 'nhan_biet', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('f309cb16-d3d6-4138-a9be-c0eaf66a0dbe', 'd7e624da-a359-4fe2-86bf-0e2827898932', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Theo quy luật phân li của Mendel, khi lai hai cơ thể thuần chủng khác nhau về một cặp tính trạng tương phản, thế hệ F1 sẽ:$q$, $q$[{"id": "A", "text": "Phân li theo tỉ lệ kiểu hình 3 trội : 1 lặn"}, {"id": "B", "text": "Đồng nhất về kiểu hình và biểu hiện tính trạng trội"}, {"id": "C", "text": "Phân li theo tỉ lệ kiểu hình 1 : 1"}, {"id": "D", "text": "Đồng nhất về kiểu hình và biểu hiện tính trạng lặn"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('17c06ddd-1149-47bf-a809-efb500483e65', 'd7e624da-a359-4fe2-86bf-0e2827898932', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Đột biến gen là dạng biến đổi nào sau đây?$q$, $q$[{"id": "A", "text": "Biến đổi số lượng NST trong tế bào sinh dưỡng"}, {"id": "B", "text": "Biến đổi trong cấu trúc của một gen cụ thể trên NST"}, {"id": "C", "text": "Biến đổi hình thái và sinh lý của cơ thể"}, {"id": "D", "text": "Sự trao đổi chéo giữa các NST không tương đồng"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('48fa53ec-c117-44fd-b342-22cb411c895c', 'd7e624da-a359-4fe2-86bf-0e2827898932', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Ở người, bệnh mù màu đỏ-lục do gen lặn liên kết X (Xᵃ). Bố bình thường (XᴬY), mẹ mang gen dị hợp (XᴬXᵃ). Xác suất sinh con trai bị mù màu là:$q$, $q$[{"id": "A", "text": "0%"}, {"id": "B", "text": "25%"}, {"id": "C", "text": "50%"}, {"id": "D", "text": "100%"}]$q$::jsonb, $q${"selected": ["C"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('3195f2f6-2f39-4759-88c9-388cc8f8585e', 'd7e624da-a359-4fe2-86bf-0e2827898932', '07c265a0-4938-43fd-a5af-a69509523d8b', 'multiple_choice', $q$Quần thể ngẫu phối ở trạng thái cân bằng Hardy-Weinberg có tần số alen A = 0,6 và alen a = 0,4. Tần số kiểu gen AA trong quần thể là:$q$, $q$[{"id": "A", "text": "0,16"}, {"id": "B", "text": "0,36"}, {"id": "C", "text": "0,48"}, {"id": "D", "text": "0,60"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('b75a93b9-e4bc-4294-a541-dcfccd7c6586', 'd7e624da-a359-4fe2-86bf-0e2827898932', '07c265a0-4938-43fd-a5af-a69509523d8b', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu sau về cơ chế di truyền ở cấp độ phân tử:$q$, $q$[{"id": "1", "statement": "Phân tử ADN có cấu trúc xoắn kép gồm 4 loại nucleotide: Adenine (A), Thymine (T), Guanine (G) và Cytosine (X/C)"}, {"id": "2", "statement": "Trong quá trình phiên mã, mạch khuôn của ADN được đọc theo chiều 3' → 5'"}, {"id": "3", "statement": "Mã di truyền có tính đặc hiệu: mỗi bộ ba mã hóa chỉ quy định duy nhất một loại axit amin"}, {"id": "4", "statement": "Mọi đột biến điểm đều gây hại cho sinh vật vì làm thay đổi cấu trúc protein"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": false}}$q$::jsonb, 'thong_hieu', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('876c326e-237c-4abf-935e-f3ca99c21606', 'd7e624da-a359-4fe2-86bf-0e2827898932', '07c265a0-4938-43fd-a5af-a69509523d8b', 'true_false', $q$Phân tích các phát biểu về tiến hóa và sinh thái học:$q$, $q$[{"id": "1", "statement": "Chọn lọc tự nhiên tác động trực tiếp lên kiểu gen, gián tiếp lên kiểu hình"}, {"id": "2", "statement": "Cách li sinh sản giữa các quần thể là điều kiện cần thiết để hình thành loài mới"}, {"id": "3", "statement": "Chuỗi thức ăn càng dài thì tổng năng lượng thất thoát qua mỗi bậc dinh dưỡng càng nhiều"}, {"id": "4", "statement": "Trong mối quan hệ cộng sinh, cả hai loài đều có lợi và không thể sống thiếu nhau"}]$q$::jsonb, $q${"answers": {"1": false, "2": true, "3": true, "4": true}}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('a4816208-6e29-4f72-83b3-5b46f89f5490', 'd7e624da-a359-4fe2-86bf-0e2827898932', '07c265a0-4938-43fd-a5af-a69509523d8b', 'essay', $q$Trình bày cơ chế điều hòa hoạt động gen theo mô hình Operon Lac ở vi khuẩn E. coli. Nêu ý nghĩa thực tiễn của mô hình này.$q$, NULL, $q${"sample": "Cấu trúc Operon Lac gồm: Gen điều hòa R (nằm ngoài operon, mã hóa protein ức chế), Vùng khởi động P (promoter, nơi RNA polymerase bám vào), Vùng vận hành O (operator, nơi protein ức chế gắn vào), Các gen cấu trúc Z, Y, A (mã hóa enzyme phân giải lactose).\nCơ chế hoạt động:\n- Khi không có lactose: protein ức chế (do gen R tạo ra) gắn vào vùng O, ngăn RNA polymerase phiên mã → gen cấu trúc không được biểu hiện → tiết kiệm năng lượng.\n- Khi có lactose: một dạng chuyển hóa của lactose (allolactose) liên kết với protein ức chế, làm thay đổi cấu hình không gian của protein ức chế → protein ức chế tách khỏi vùng O → RNA polymerase tiến hành phiên mã các gen Z, Y, A → tổng hợp enzyme phân giải lactose.\nÝ nghĩa thực tiễn: Hiểu cơ chế điều hòa gen giúp ứng dụng trong công nghệ sinh học như sản xuất protein tái tổ hợp (insulin, hormone tăng trưởng), phát triển kháng sinh, nghiên cứu ung thư.", "keywords": ["operon", "lactose", "allolactose", "protein ức chế", "promoter", "operator", "RNA polymerase", "gen cấu trúc", "E.coli", "công nghệ sinh học"]}$q$::jsonb, 'van_dung', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('aaa8cb58-8872-4f98-9e65-b68094a0e74d', 'd7e624da-a359-4fe2-86bf-0e2827898932', '07c265a0-4938-43fd-a5af-a69509523d8b', 'essay', $q$Trình bày nội dung thuyết tiến hóa tổng hợp hiện đại. So sánh với học thuyết tiến hóa của Darwin và chỉ ra những điểm kế thừa và bổ sung.$q$, NULL, $q${"sample": "Thuyết tiến hóa tổng hợp hiện đại (thế kỷ XX) kết hợp học thuyết Darwin với di truyền học hiện đại.\nNội dung: Đơn vị tiến hóa là quần thể (không phải cá thể). Các nhân tố tiến hóa gồm: đột biến (tạo nguồn biến dị), chọn lọc tự nhiên (nhân tố định hướng), di nhập gen (gene flow), biến động di truyền (genetic drift), giao phối không ngẫu nhiên.\nSo sánh với Darwin:\n- Điểm kế thừa: Chọn lọc tự nhiên là lực lượng chính định hướng tiến hóa; đấu tranh sinh tồn; biến dị cá thể là nguyên liệu tiến hóa.\n- Điểm bổ sung: Darwin không biết cơ chế di truyền (chưa có di truyền học); thuyết hiện đại giải thích được nguồn gốc biến dị (đột biến gen, NST); xác định đơn vị tiến hóa là quần thể; giải thích được tiến hóa trung tính (Kimura).", "keywords": ["tiến hóa", "chọn lọc tự nhiên", "đột biến", "quần thể", "Darwin", "di truyền", "biến dị", "di nhập gen", "biến động di truyền"]}$q$::jsonb, 'thong_hieu', TRUE, 'f1fba76b-d17c-4e2c-83b7-d633a7276247', NOW()),
('70ed5d13-5d5e-498c-9487-405177f33056', '20b3394a-dae3-407c-9e66-9f199f92994c', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Nhà nước Văn Lang - nhà nước đầu tiên trong lịch sử Việt Nam, được thành lập vào khoảng thời gian nào?$q$, $q$[{"id": "A", "text": "Thế kỷ X trước Công nguyên"}, {"id": "B", "text": "Khoảng thế kỷ VII - VI trước Công nguyên"}, {"id": "C", "text": "Thế kỷ III trước Công nguyên"}, {"id": "D", "text": "Đầu Công nguyên (thế kỷ I)"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('32a4d4cb-a0b2-42d6-a859-ddb7433ad1e9', '20b3394a-dae3-407c-9e66-9f199f92994c', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Khởi nghĩa Hai Bà Trưng (năm 40 - 43 SCN) nổ ra xuất phát từ nguyên nhân chủ yếu nào sau đây?$q$, $q$[{"id": "A", "text": "Muốn thành lập một vương quốc độc lập riêng"}, {"id": "B", "text": "Phản kháng ách đô hộ hà khắc của nhà Hán và trả thù cho chồng bà Trưng Trắc bị giết"}, {"id": "C", "text": "Tranh giành quyền lực chính trị với thái thú Tô Định"}, {"id": "D", "text": "Do hạn hán và mất mùa liên tiếp khiến dân chúng nổi dậy"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('250697d2-18ed-4c87-98a8-2ff6c9a4c9c6', '20b3394a-dae3-407c-9e66-9f199f92994c', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Chiến thắng Bạch Đằng năm 938 do Ngô Quyền lãnh đạo có ý nghĩa lịch sử nào sau đây?$q$, $q$[{"id": "A", "text": "Hoàn toàn chấm dứt 1000 năm Bắc thuộc, đất nước độc lập hoàn toàn ngay sau đó"}, {"id": "B", "text": "Mở ra thời kỳ độc lập, tự chủ lâu dài cho dân tộc Việt Nam sau hơn 1000 năm đô hộ"}, {"id": "C", "text": "Thành lập nhà nước phong kiến tập quyền đầu tiên của Việt Nam"}, {"id": "D", "text": "Mở rộng lãnh thổ Đại Việt về phía Nam"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('3fdba3f4-4deb-4c50-a13c-8ffcec38506f', '20b3394a-dae3-407c-9e66-9f199f92994c', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Nhìn lại lịch sử kháng chiến chống ngoại xâm thời phong kiến Việt Nam (chống Tống, Mông-Nguyên, Minh...), yếu tố nào là quyết định nhất dẫn đến thắng lợi?$q$, $q$[{"id": "A", "text": "Địa hình hiểm trở của Việt Nam gây bất lợi cho quân xâm lược"}, {"id": "B", "text": "Đường lối kháng chiến đúng đắn của bộ chỉ huy và sức mạnh đoàn kết toàn dân"}, {"id": "C", "text": "Quân xâm lược thiếu vũ khí và lương thực"}, {"id": "D", "text": "Sự hỗ trợ quân sự và kinh tế của các nước láng giềng"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('d717c9c4-d6e4-4ed4-bce1-659573190033', '20b3394a-dae3-407c-9e66-9f199f92994c', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu sau về lịch sử Việt Nam thời cổ đại:$q$, $q$[{"id": "1", "statement": "Nhà nước Văn Lang do Hùng Vương đứng đầu, đóng đô tại Phong Châu (nay thuộc Phú Thọ)"}, {"id": "2", "statement": "An Dương Vương xây dựng thành Cổ Loa để bảo vệ nhà nước Âu Lạc"}, {"id": "3", "statement": "Nước Âu Lạc tồn tại từ năm 258 TCN đến 179 TCN (khi bị Triệu Đà thôn tính)"}, {"id": "4", "statement": "Thời kỳ Bắc thuộc kéo dài từ năm 179 TCN đến năm 938 SCN"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('1eb347d6-a1bd-4e8b-b9b2-71f8f5837689', '20b3394a-dae3-407c-9e66-9f199f92994c', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'true_false', $q$Phân tích các nhận định sau về thời kỳ Bắc thuộc và các cuộc khởi nghĩa:$q$, $q$[{"id": "1", "statement": "Trong suốt thời kỳ Bắc thuộc, người Việt đã bị đồng hóa hoàn toàn về văn hóa và tiếng nói"}, {"id": "2", "statement": "Các cuộc khởi nghĩa liên tiếp nổ ra trong thời Bắc thuộc thể hiện tinh thần bất khuất của dân tộc"}, {"id": "3", "statement": "Khởi nghĩa Lý Bí (544 SCN) thành công, lập ra nhà nước Vạn Xuân"}, {"id": "4", "statement": "Mai Thúc Loan (Mai Hắc Đế) lãnh đạo cuộc khởi nghĩa vào đầu thế kỷ VIII"}]$q$::jsonb, $q${"answers": {"1": false, "2": true, "3": true, "4": true}}$q$::jsonb, 'thong_hieu', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('79d816ec-dd70-486d-81a6-293c44123d5c', '20b3394a-dae3-407c-9e66-9f199f92994c', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'essay', $q$Phân tích ý nghĩa lịch sử của chiến thắng Bạch Đằng năm 938 đối với sự nghiệp xây dựng và bảo vệ đất nước của dân tộc Việt Nam.$q$, NULL, $q${"sample": "Ý nghĩa của chiến thắng Bạch Đằng năm 938:\n1. Kết thúc thời kỳ Bắc thuộc: Chiến thắng chấm dứt hơn 1000 năm đô hộ của phong kiến phương Bắc (từ 179 TCN đến 938 SCN), mở ra kỷ nguyên độc lập, tự chủ lâu dài cho dân tộc Việt Nam.\n2. Thể hiện tài thao lược quân sự xuất sắc của Ngô Quyền với chiến thuật dùng cọc nhọn bịt sắt cắm xuống lòng sông Bạch Đằng lợi dụng thủy triều.\n3. Khẳng định sức mạnh đoàn kết của nhân dân Việt Nam trong đấu tranh chống ngoại xâm.\n4. Đặt nền tảng vững chắc cho sự hình thành và phát triển của các triều đại phong kiến độc lập tiếp theo: Đinh, Tiền Lê, Lý, Trần...", "keywords": ["Bạch Đằng", "Ngô Quyền", "Bắc thuộc", "độc lập", "cọc nhọn", "938", "thủy triều", "dân tộc", "kỷ nguyên"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('3bf7102d-0815-44f2-bd00-f9175f84e270', '20b3394a-dae3-407c-9e66-9f199f92994c', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'essay', $q$So sánh tổ chức bộ máy nhà nước thời Văn Lang - Âu Lạc với nhà nước phong kiến thời Lý - Trần. Rút ra nhận xét về sự phát triển của nhà nước Việt Nam.$q$, NULL, $q${"sample": "Nhà nước Văn Lang - Âu Lạc (sơ khai):\n- Đứng đầu: Hùng Vương / An Dương Vương\n- Giúp việc: Lạc hầu (quan văn), Lạc tướng (quan võ và địa phương)\n- Chưa có luật thành văn, chưa có thi cử, bộ máy đơn giản\nNhà nước Lý - Trần (phong kiến phát triển):\n- Hoàn thiện hệ thống quan lại trung ương đến địa phương\n- Nhà Lý ban hành bộ luật Hình thư (1042) - bộ luật thành văn đầu tiên\n- Mở khoa thi Nho học (1075) để tuyển chọn nhân tài\n- Xây dựng quân đội chính quy, quân địa phương\nNhận xét: Nhà nước Việt Nam phát triển từ đơn giản, sơ khai lên hoàn thiện. Thể hiện sự trưởng thành của dân tộc trong xây dựng thể chế chính trị.", "keywords": ["Văn Lang", "Âu Lạc", "Lý", "Trần", "Hình thư", "thi cử", "quan lại", "phong kiến", "tập quyền", "Hùng Vương"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('1bef158e-68d9-4459-aa4d-5b7dbddca544', '3aea141a-1c64-449a-ad50-0657b9aae9e1', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Phong trào Cần Vương (1885 - 1896) bùng nổ trực tiếp từ sự kiện nào sau đây?$q$, $q$[{"id": "A", "text": "Hiệp ước Nhâm Tuất (1862) triều Nguyễn cắt đất cho Pháp"}, {"id": "B", "text": "Vua Hàm Nghi xuống chiếu Cần Vương kêu gọi nhân dân đứng lên giúp vua cứu nước"}, {"id": "C", "text": "Hiệp ước Patenôtre (1884) đặt nền bảo hộ Pháp"}, {"id": "D", "text": "Thực dân Pháp tấn công Đà Nẵng năm 1858"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('080a17e3-39d1-4c64-9395-134f169882ea', '3aea141a-1c64-449a-ad50-0657b9aae9e1', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Cuộc khai thác thuộc địa lần thứ nhất của Pháp (1897 - 1914) đã tạo ra sự thay đổi quan trọng nhất nào trong xã hội Việt Nam?$q$, $q$[{"id": "A", "text": "Phát triển được một nền kinh tế công nghiệp độc lập cho Việt Nam"}, {"id": "B", "text": "Làm xuất hiện các giai cấp và tầng lớp xã hội mới như giai cấp công nhân, tầng lớp tư sản, tiểu tư sản"}, {"id": "C", "text": "Nâng cao đời sống vật chất và tinh thần của toàn thể nhân dân"}, {"id": "D", "text": "Xây dựng một hệ thống giáo dục hiện đại theo mô hình phương Tây"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('af5490ef-5890-4368-954c-adad00e13f6b', '3aea141a-1c64-449a-ad50-0657b9aae9e1', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Xu hướng cứu nước của Phan Bội Châu (bạo động) và Phan Châu Trinh (cải cách) khác nhau cơ bản ở điểm nào?$q$, $q$[{"id": "A", "text": "Phương pháp đấu tranh và thái độ đối với thực dân Pháp"}, {"id": "B", "text": "Mục tiêu cuối cùng là giành độc lập dân tộc"}, {"id": "C", "text": "Đối tượng vận động và tập hợp lực lượng"}, {"id": "D", "text": "Xuất thân và địa vị xã hội của hai nhà lãnh đạo"}]$q$::jsonb, $q${"selected": ["A"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('80af12dc-1713-4875-9834-5c9ee5702509', '3aea141a-1c64-449a-ad50-0657b9aae9e1', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Nguyên nhân sâu xa nhất khiến các phong trào yêu nước Việt Nam đầu thế kỷ XX (Đông Du, Duy Tân, Đông Kinh Nghĩa Thục...) đều thất bại là gì?$q$, $q$[{"id": "A", "text": "Thiếu vũ khí hiện đại và lực lượng quân sự đủ mạnh"}, {"id": "B", "text": "Chưa có đường lối cách mạng đúng đắn, thiếu tổ chức chặt chẽ và chưa tập hợp được sức mạnh toàn thể nhân dân"}, {"id": "C", "text": "Thực dân Pháp quá mạnh so với lực lượng trong nước"}, {"id": "D", "text": "Thiếu sự ủng hộ và viện trợ từ cộng đồng quốc tế"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('8ce04ac2-93ba-418f-bfd1-4f9d192f1327', '3aea141a-1c64-449a-ad50-0657b9aae9e1', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu sau về quá trình thực dân Pháp xâm lược Việt Nam:$q$, $q$[{"id": "1", "statement": "Thực dân Pháp nổ súng tấn công Đà Nẵng ngày 1/9/1858, mở đầu cuộc chiến tranh xâm lược Việt Nam"}, {"id": "2", "statement": "Hiệp ước Nhâm Tuất (1862) triều Nguyễn nhượng 3 tỉnh miền Đông Nam Kỳ (Gia Định, Định Tường, Biên Hòa) cho Pháp"}, {"id": "3", "statement": "Hiệp ước Giáp Tuất (1874) thừa nhận toàn bộ 6 tỉnh Nam Kỳ là thuộc địa của Pháp"}, {"id": "4", "statement": "Hiệp ước Patenôtre (6/6/1884) chính thức đặt toàn bộ Việt Nam dưới sự bảo hộ của Pháp"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('003669c6-459f-4e2e-944f-ab54bf5a45a3', '3aea141a-1c64-449a-ad50-0657b9aae9e1', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'true_false', $q$Nhận định về các nhà yêu nước tiêu biểu đầu thế kỷ XX:$q$, $q$[{"id": "1", "statement": "Phan Bội Châu chủ trương dựa vào sự giúp đỡ của Nhật Bản để đánh đuổi thực dân Pháp"}, {"id": "2", "statement": "Phan Châu Trinh đề cao phương pháp bạo động vũ trang để lật đổ thực dân Pháp"}, {"id": "3", "statement": "Hoàng Hoa Thám (Đề Thám) lãnh đạo nghĩa quân Yên Thế chiến đấu kiên cường hơn 30 năm"}, {"id": "4", "statement": "Phong trào Đông Kinh Nghĩa Thục (1907) cổ vũ việc học chữ Quốc ngữ và truyền bá tư tưởng dân chủ"}]$q$::jsonb, $q${"answers": {"1": true, "2": false, "3": true, "4": true}}$q$::jsonb, 'thong_hieu', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('08bdee1f-b9b4-44b2-b3c6-0f96cd86df3e', '3aea141a-1c64-449a-ad50-0657b9aae9e1', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'essay', $q$Phân tích những hạn chế của các phong trào yêu nước Việt Nam cuối thế kỷ XIX - đầu thế kỷ XX. Từ đó rút ra bài học lịch sử cho cách mạng Việt Nam.$q$, NULL, $q${"sample": "Những hạn chế chủ yếu:\n1. Thiếu đường lối cách mạng đúng đắn và khoa học: Phong trào Cần Vương dựa vào tư tưởng phong kiến đã lỗi thời; Đông Du trông chờ vào ngoại lực (Nhật Bản) sai lầm; Duy Tân thiếu lực lượng xã hội đủ mạnh.\n2. Chưa tập hợp được đông đảo quần chúng nhân dân lao động (công nhân, nông dân) - lực lượng cách mạng chủ yếu.\n3. Chưa có một tổ chức cách mạng thống nhất, chặt chẽ với kỷ luật nghiêm minh.\n4. Chưa có giai cấp lãnh đạo tiên tiến (giai cấp công nhân chưa trưởng thành).\nBài học lịch sử:\n- Phải có đường lối cách mạng đúng đắn, phù hợp với quy luật khách quan\n- Phải xây dựng tổ chức cách mạng vững mạnh\n- Phải đoàn kết toàn dân, đặc biệt là công - nông\n- Phải kết hợp đấu tranh chính trị với đấu tranh vũ trang", "keywords": ["hạn chế", "Cần Vương", "Đông Du", "Duy Tân", "đường lối", "quần chúng", "tổ chức", "giai cấp công nhân", "bài học"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('b88d1447-912c-4fec-b635-3c12d39994ef', '3aea141a-1c64-449a-ad50-0657b9aae9e1', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'essay', $q$Trình bày hoàn cảnh ra đời, hoạt động và ý nghĩa lịch sử của phong trào Đông Du (1905 - 1909) do Phan Bội Châu lãnh đạo.$q$, NULL, $q${"sample": "Hoàn cảnh ra đời:\n- Đầu thế kỷ XX, các phong trào yêu nước trong nước đều thất bại trước sức mạnh của thực dân Pháp.\n- Nhật Bản thắng đế quốc Nga trong cuộc chiến tranh Nga - Nhật (1905), cổ vũ mạnh mẽ tinh thần các dân tộc châu Á.\n- Phan Bội Châu thành lập Hội Duy Tân (1904), chủ trương dựa vào Nhật Bản để đánh đuổi Pháp.\nHoạt động: Tổ chức đưa hàng trăm thanh niên yêu nước sang Nhật Bản học tập quân sự và khoa học kỹ thuật (khoảng 200 người).\nÝ nghĩa:\n- Đào tạo được một số nhân tài yêu nước có tri thức mới\n- Khơi dậy mạnh mẽ tinh thần yêu nước trong nhân dân\n- Hạn chế: Chủ trương dựa vào Nhật Bản là sai lầm, thiếu cơ sở. Năm 1909, Nhật - Pháp ký hiệp ước, Nhật trục xuất lưu học sinh Việt Nam, phong trào tan rã.\nBài học: Không thể trông chờ vào ngoại lực để giải phóng dân tộc.", "keywords": ["Đông Du", "Phan Bội Châu", "Nhật Bản", "Duy Tân hội", "thanh niên", "Nga-Nhật", "1905", "lưu học sinh", "tan rã", "bài học"]}$q$::jsonb, 'nhan_biet', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('849c5ac6-95bc-406f-86b6-100d56bc5cf8', '496e8b80-dae2-40e1-b6e0-df81bc081385', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Nguyễn Ái Quốc (Hồ Chí Minh) tìm ra con đường cứu nước đúng đắn cho dân tộc Việt Nam sau khi đọc tác phẩm nào?$q$, $q$[{"id": "A", "text": "Tuyên ngôn Độc lập của Hoa Kỳ (1776)"}, {"id": "B", "text": "Sơ thảo lần thứ nhất những Luận cương về vấn đề dân tộc và thuộc địa của V.I. Lenin"}, {"id": "C", "text": "Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp (1789)"}, {"id": "D", "text": "Tư bản luận (Das Kapital) của Karl Marx"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('7403fac3-43d3-491f-a829-406b80800e46', '496e8b80-dae2-40e1-b6e0-df81bc081385', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Cách mạng tháng Tám năm 1945 ở Việt Nam thành công nhanh chóng và ít đổ máu, nguyên nhân chủ yếu nhất là gì?$q$, $q$[{"id": "A", "text": "Phát xít Nhật đầu hàng Đồng minh vô điều kiện nên không còn kháng cự"}, {"id": "B", "text": "Đảng Cộng sản Đông Dương có đường lối cách mạng đúng đắn, chuẩn bị lực lượng lâu dài và chớp thời cơ lịch sử khi Nhật đầu hàng"}, {"id": "C", "text": "Lực lượng vũ trang cách mạng đã trở nên rất mạnh về số lượng và trang bị"}, {"id": "D", "text": "Cả Pháp và Nhật đều đã kiệt sức và không còn khả năng chống đỡ"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('27af1238-8d54-44d2-ae43-c2d86dc8c2b2', '496e8b80-dae2-40e1-b6e0-df81bc081385', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Chiến dịch Điện Biên Phủ (13/3 - 7/5/1954) toàn thắng có ý nghĩa lịch sử quan trọng nhất là gì?$q$, $q$[{"id": "A", "text": "Chấm dứt hoàn toàn sự hiện diện về quân sự của Pháp tại Đông Dương"}, {"id": "B", "text": "Buộc Pháp phải ký kết Hiệp định Geneva (1954), chấm dứt chiến tranh và lập lại hòa bình ở Đông Dương"}, {"id": "C", "text": "Thống nhất đất nước Việt Nam ngay lập tức sau chiến thắng"}, {"id": "D", "text": "Buộc đế quốc Mỹ phải rút quân khỏi miền Nam Việt Nam"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('1fe604bd-a539-48f6-bf99-1bdacafbba55', '496e8b80-dae2-40e1-b6e0-df81bc081385', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'multiple_choice', $q$Phân tích nguyên nhân quyết định thắng lợi của cuộc kháng chiến chống Mỹ cứu nước (1954 - 1975) của nhân dân Việt Nam?$q$, $q$[{"id": "A", "text": "Sự viện trợ vũ khí và kinh tế to lớn của Liên Xô và Trung Quốc"}, {"id": "B", "text": "Sự lãnh đạo sáng suốt của Đảng, tinh thần đoàn kết chiến đấu của toàn dân và sự ủng hộ của nhân dân tiến bộ thế giới"}, {"id": "C", "text": "Phong trào phản chiến mạnh mẽ trong nước Mỹ làm suy yếu ý chí chiến đấu"}, {"id": "D", "text": "Quân đội và chính quyền Việt Nam Cộng hòa không có ý chí và năng lực chiến đấu"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('51a3dc61-44a3-47d1-a035-a678769aa444', '496e8b80-dae2-40e1-b6e0-df81bc081385', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu về giai đoạn lịch sử 1930 - 1945:$q$, $q$[{"id": "1", "statement": "Đảng Cộng sản Việt Nam được thành lập ngày 3 tháng 2 năm 1930 tại Hương Cảng (Trung Quốc)"}, {"id": "2", "statement": "Phong trào Xô viết Nghệ - Tĩnh (1930 - 1931) là đỉnh cao của phong trào cách mạng 1930 - 1931"}, {"id": "3", "statement": "Mặt trận Việt Minh được thành lập ngày 19/5/1941 tại Pắc Bó (Cao Bằng)"}, {"id": "4", "statement": "Tổng khởi nghĩa tháng Tám 1945 diễn ra và thành công trên cả nước chỉ trong vòng khoảng 2 tuần"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('710cd8cd-2297-4626-92d1-267132d2cc73', '496e8b80-dae2-40e1-b6e0-df81bc081385', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'true_false', $q$Nhận định về cuộc kháng chiến chống thực dân Pháp (1945 - 1954):$q$, $q$[{"id": "1", "statement": "Chiến dịch Việt Bắc Thu - Đông (1947) quân và dân ta đánh bại kế hoạch tấn công lên Việt Bắc của Pháp"}, {"id": "2", "statement": "Chiến dịch Biên giới Thu - Đông (1950) đã giải phóng toàn bộ vùng biên giới Việt - Trung"}, {"id": "3", "statement": "Đại tướng Võ Nguyên Giáp được giao nhiệm vụ Tổng chỉ huy chiến dịch Điện Biên Phủ"}, {"id": "4", "statement": "Hiệp định Geneva (7/1954) quy định lấy vĩ tuyến 17 làm ranh giới quân sự tạm thời"}]$q$::jsonb, $q${"answers": {"1": true, "2": false, "3": true, "4": true}}$q$::jsonb, 'thong_hieu', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('9e2e430d-931d-4ba5-b5b2-509db482da67', '496e8b80-dae2-40e1-b6e0-df81bc081385', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'essay', $q$Phân tích ý nghĩa lịch sử và bài học kinh nghiệm của Cách mạng tháng Tám năm 1945 đối với sự nghiệp cách mạng Việt Nam.$q$, NULL, $q${"sample": "Ý nghĩa lịch sử:\n1. Đối với Việt Nam: Phá tan xiềng xích nô lệ của thực dân Pháp và phát xít Nhật (gần 90 năm), lật đổ chế độ quân chủ phong kiến. Khai sinh nước Việt Nam Dân chủ Cộng hòa ngày 2/9/1945 - nhà nước dân chủ nhân dân đầu tiên ở Đông Nam Á, đưa nhân dân lên địa vị làm chủ đất nước.\n2. Đối với thế giới: Cổ vũ mạnh mẽ phong trào giải phóng dân tộc trên thế giới, đặc biệt ở châu Á và châu Phi.\nBài học kinh nghiệm:\n1. Có sự lãnh đạo của Đảng Cộng sản mác-xít với đường lối cách mạng đúng đắn\n2. Xây dựng lực lượng chính trị và vũ trang toàn diện, vững mạnh\n3. Nắm vững và chớp đúng thời cơ lịch sử (Nhật đầu hàng Đồng minh)\n4. Kết hợp đấu tranh chính trị với đấu tranh vũ trang\n5. Xây dựng và giữ vững Mặt trận đoàn kết dân tộc rộng rãi (Việt Minh)", "keywords": ["Cách mạng tháng Tám", "2/9/1945", "Việt Nam DCCH", "Đảng", "thời cơ", "Việt Minh", "đoàn kết", "phong kiến", "bài học"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('4576ce46-b733-4dd9-b0fe-80b868024e00', '496e8b80-dae2-40e1-b6e0-df81bc081385', '97935335-2ce9-4bf8-90a5-41ffe9cbed4e', 'essay', $q$Trình bày diễn biến chính và phân tích ý nghĩa của Chiến dịch Hồ Chí Minh (tháng 4/1975) trong tiến trình lịch sử Việt Nam.$q$, NULL, $q${"sample": "Diễn biến:\n- Ngày 26/4/1975: Năm cánh quân của Quân giải phóng miền Nam đồng loạt mở cuộc tổng tấn công vào Sài Gòn.\n- Ngày 28/4/1975: Phi công Nguyễn Thành Trung ném bom sân bay Tân Sơn Nhất.\n- Sáng 30/4/1975: Các đơn vị quân giải phóng tiến vào các mục tiêu then chốt. Xe tăng 843 húc đổ cánh cổng phụ, xe tăng 390 húc đổ cổng chính Dinh Độc Lập lúc 11h30.\n- 11h30 ngày 30/4/1975: Tổng thống chính quyền Sài Gòn Dương Văn Minh tuyên bố đầu hàng vô điều kiện. Chiến dịch Hồ Chí Minh toàn thắng.\nÝ nghĩa lịch sử:\n1. Kết thúc 30 năm chiến tranh cách mạng, giải phóng miền Nam, thống nhất đất nước.\n2. Đập tan hoàn toàn cuộc chiến tranh xâm lược và ách thống trị của đế quốc Mỹ.\n3. Là chiến thắng vĩ đại nhất trong lịch sử chống ngoại xâm của dân tộc Việt Nam.\n4. Cổ vũ mạnh mẽ phong trào giải phóng dân tộc, hòa bình, dân chủ trên thế giới.", "keywords": ["Chiến dịch Hồ Chí Minh", "30/4/1975", "Dương Văn Minh", "Dinh Độc Lập", "thống nhất", "xe tăng 390", "năm cánh quân", "đầu hàng", "giải phóng"]}$q$::jsonb, 'van_dung', TRUE, 'f8e978d3-2f3c-4020-ac54-7be912f023f6', NOW()),
('5de9ad2d-e981-4133-b3e3-bb77c27ea69e', '96aa9c44-11c9-41fc-a0f0-89d3eb060b49', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Trái Đất có hình dạng thực tế là:$q$, $q$[{"id": "A", "text": "Hình cầu hoàn hảo, đối xứng hoàn toàn"}, {"id": "B", "text": "Hình elipsoid (cầu dẹt) - hơi dẹt ở hai cực và phình ra ở xích đạo"}, {"id": "C", "text": "Hình trụ tròn kéo dài theo trục Bắc - Nam"}, {"id": "D", "text": "Hình lập phương với 6 mặt phẳng"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
