('19cf9b97-1501-4ff2-87fc-650526885db9', '96aa9c44-11c9-41fc-a0f0-89d3eb060b49', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Khu vực nào ở châu Á có khí hậu nhiệt đới gió mùa điển hình nhất?$q$, $q$[{"id": "A", "text": "Bán đảo Ả Rập (Tây Nam Á)"}, {"id": "B", "text": "Nam Á (Ấn Độ) và Đông Nam Á"}, {"id": "C", "text": "Đông Bắc Á (Nhật Bản, Hàn Quốc)"}, {"id": "D", "text": "Trung Á (Kazakhstan, Uzbekistan)"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('efaf959a-bdea-44cd-a016-e9a60e3ec2cc', '96aa9c44-11c9-41fc-a0f0-89d3eb060b49', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Trong bối cảnh biến đổi khí hậu toàn cầu hiện nay, khu vực nào của Việt Nam sẽ chịu tác động tiêu cực nghiêm trọng nhất trong tương lai gần?$q$, $q$[{"id": "A", "text": "Vùng núi Tây Bắc do hiện tượng băng tan"}, {"id": "B", "text": "Đồng bằng sông Cửu Long do nước biển dâng và xâm nhập mặn ngày càng sâu"}, {"id": "C", "text": "Vùng Đông Bắc do mưa axit từ các nước công nghiệp"}, {"id": "D", "text": "Tây Nguyên do hạn hán và sa mạc hóa cực đoan"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('7f6f4da1-5e35-47f4-93ca-cf58a87e0191', '96aa9c44-11c9-41fc-a0f0-89d3eb060b49', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu về cấu tạo bên trong của Trái Đất:$q$, $q$[{"id": "1", "statement": "Vỏ Trái Đất là lớp ngoài cùng và mỏng nhất trong cấu trúc Trái Đất"}, {"id": "2", "statement": "Lớp Manti (lớp trung gian) chiếm phần lớn thể tích và khối lượng Trái Đất"}, {"id": "3", "statement": "Nhân Trái Đất gồm nhân ngoài (ở trạng thái lỏng) và nhân trong (ở trạng thái rắn)"}, {"id": "4", "statement": "Nhiệt độ và áp suất đều tăng dần theo độ sâu từ vỏ Trái Đất xuống đến nhân"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('b67da2a1-e2a6-4837-be62-ccfd910bbe20', '96aa9c44-11c9-41fc-a0f0-89d3eb060b49', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'true_false', $q$Phân tích các nhận định về thủy quyển và khí quyển Trái Đất:$q$, $q$[{"id": "1", "statement": "Thái Bình Dương là đại dương lớn nhất và sâu nhất trên Trái Đất"}, {"id": "2", "statement": "Nước ngọt chỉ chiếm khoảng 3% tổng lượng nước trên Trái Đất, phần lớn đóng băng ở hai cực"}, {"id": "3", "statement": "Tầng đối lưu (troposphere) là nơi xảy ra hầu hết các hiện tượng thời tiết như mưa, bão, gió"}, {"id": "4", "statement": "Tầng ozone nằm ở tầng bình lưu (stratosphere), có tác dụng hấp thụ tia cực tím bảo vệ sự sống"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": true}}$q$::jsonb, 'thong_hieu', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('f05e56ce-9410-4bfb-8da6-e9a53fcf776c', '96aa9c44-11c9-41fc-a0f0-89d3eb060b49', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'essay', $q$Giải thích tại sao các đô thị lớn trên thế giới thường hình thành và phát triển ở vùng đồng bằng ven sông hoặc ven biển. Cho ví dụ minh họa.$q$, NULL, $q${"sample": "Các đô thị lớn hình thành ở đồng bằng ven sông/ven biển vì những lý do sau:\n1. Địa hình thuận lợi: Đồng bằng bằng phẳng thuận tiện cho xây dựng công trình, giao thông đi lại.\n2. Nông nghiệp phát triển: Đất phù sa màu mỡ, nguồn nước dồi dào giúp phát triển nông nghiệp, cung cấp lương thực cho đô thị.\n3. Giao thông thủy thuận lợi: Sông và biển là tuyến đường giao thương quan trọng, tạo điều kiện cho thương mại phát triển.\n4. Nguồn nước phục vụ sinh hoạt và sản xuất.\nVí dụ:\n- Hà Nội: tọa lạc trên đồng bằng sông Hồng, gần sông Hồng và sông Đuống.\n- TP. Hồ Chí Minh: hạ lưu sông Đồng Nai, Sài Gòn, cận biển.\n- London (Anh): hai bên bờ sông Thames.\n- Thượng Hải (Trung Quốc): hạ lưu sông Dương Tử, cận biển.\n- New York (Mỹ): cảng biển tự nhiên ở cửa sông Hudson.", "keywords": ["đô thị", "đồng bằng", "ven sông", "ven biển", "giao thông thủy", "phù sa", "nông nghiệp", "thương mại", "Hà Nội", "TP.HCM"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('b8bed775-10ab-45a0-8aac-bc49c691ae55', '96aa9c44-11c9-41fc-a0f0-89d3eb060b49', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'essay', $q$Phân tích mối quan hệ giữa vị trí địa lý và đặc điểm khí hậu của một vùng lãnh thổ. Tại sao Việt Nam có khí hậu nhiệt đới ẩm gió mùa?$q$, NULL, $q${"sample": "Mối quan hệ giữa vị trí địa lý và khí hậu:\n- Vĩ độ địa lý quyết định lượng bức xạ Mặt Trời nhận được và kiểu khí hậu cơ bản (nhiệt đới, ôn đới, hàn đới).\n- Vị trí gần/xa đại dương ảnh hưởng đến độ ẩm và tính chất khí hậu (lục địa hay hải dương).\n- Địa hình chắn gió tạo ra sự phân hóa khí hậu theo sườn đón gió và khuất gió.\nTại sao Việt Nam có khí hậu nhiệt đới ẩm gió mùa:\n1. Vị trí vĩ độ: Nằm trong vành đai nhiệt đới Bắc bán cầu (8°B - 23°B) → nhận được lượng bức xạ Mặt Trời lớn → nền nhiệt cao.\n2. Tiếp giáp Biển Đông rộng lớn → nguồn ẩm dồi dào, mưa nhiều.\n3. Ảnh hưởng của gió mùa châu Á: Gió mùa Tây Nam (mùa hạ) mang mưa từ Ấn Độ Dương; Gió mùa Đông Bắc (mùa đông) khô lạnh từ lục địa châu Á.\n4. Dãy Trường Sơn chạy dọc đất nước tạo ra sự phân hóa khí hậu Đông - Tây rõ rệt.", "keywords": ["vị trí địa lý", "khí hậu", "nhiệt đới", "gió mùa", "Việt Nam", "Biển Đông", "Trường Sơn", "vĩ độ", "độ ẩm"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
