('b844d39d-262b-4940-a955-130dbe3fc103', 'd5954a9e-8506-4f5b-b327-257fa6d9839d', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Toàn cầu hóa kinh tế được biểu hiện rõ nét nhất qua xu hướng nào sau đây?$q$, $q$[{"id": "A", "text": "Các quốc gia ngày càng đóng cửa và tăng cường bảo hộ thị trường nội địa"}, {"id": "B", "text": "Tăng cường thương mại quốc tế, đầu tư trực tiếp xuyên quốc gia và vai trò ngày càng lớn của công ty đa quốc gia"}, {"id": "C", "text": "Sự đồng nhất hoàn toàn về văn hóa và lối sống trên toàn thế giới"}, {"id": "D", "text": "Giảm dần khoảng cách giàu nghèo giữa các quốc gia phát triển và đang phát triển"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('cfc92421-c7cc-43de-9e4c-318c343a76f8', 'd5954a9e-8506-4f5b-b327-257fa6d9839d', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Hiệp hội các quốc gia Đông Nam Á (ASEAN) được thành lập năm 1967 tại đâu và có bao nhiêu quốc gia sáng lập?$q$, $q$[{"id": "A", "text": "Thủ đô Manila (Philippines) - 5 quốc gia sáng lập"}, {"id": "B", "text": "Thủ đô Bangkok (Thái Lan) - 5 quốc gia sáng lập"}, {"id": "C", "text": "Thủ đô Jakarta (Indonesia) - 6 quốc gia sáng lập"}, {"id": "D", "text": "Thủ đô Singapore - 6 quốc gia sáng lập"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('eba61055-1e86-4900-b831-249bc229c009', 'd5954a9e-8506-4f5b-b327-257fa6d9839d', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Cuộc Cách mạng công nghiệp 4.0 sẽ tác động như thế nào đến sự phân bố dân cư và quá trình đô thị hóa toàn cầu trong thế kỷ XXI?$q$, $q$[{"id": "A", "text": "Dân cư sẽ phân tán và tập trung nhiều hơn ở các vùng nông thôn"}, {"id": "B", "text": "Hình thành các siêu đô thị thông minh, dân cư tập trung ở những vùng có hạ tầng số và kết nối internet tốt"}, {"id": "C", "text": "Phân bố dân cư không có thay đổi đáng kể so với thế kỷ XX"}, {"id": "D", "text": "Đô thị hóa sẽ chậm lại do nhiều người có thể làm việc từ xa ở nông thôn"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('17cbaa02-ed18-4c66-bdef-4ac041878cf7', 'd5954a9e-8506-4f5b-b327-257fa6d9839d', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu về địa lý dân cư thế giới:$q$, $q$[{"id": "1", "statement": "Dân số thế giới năm 2024 đã vượt mốc 8 tỉ người"}, {"id": "2", "statement": "Châu Á là châu lục đông dân nhất thế giới, chiếm hơn 50% dân số toàn cầu"}, {"id": "3", "statement": "Tỉ suất sinh ở các nước phát triển thường cao hơn so với các nước đang phát triển"}, {"id": "4", "statement": "Đô thị hóa quá nhanh có thể gây ra các vấn đề như ô nhiễm môi trường, thất nghiệp và phân hóa xã hội"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": false, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('5ce61d90-3534-43ad-9da8-907c9d50e0fb', 'd5954a9e-8506-4f5b-b327-257fa6d9839d', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'true_false', $q$Nhận định về tổ chức ASEAN và hợp tác khu vực Đông Nam Á:$q$, $q$[{"id": "1", "statement": "ASEAN hiện có 10 quốc gia thành viên (tính đến năm 2024)"}, {"id": "2", "statement": "Cộng đồng Kinh tế ASEAN (AEC) chính thức được tuyên bố thành lập vào ngày 31/12/2015"}, {"id": "3", "statement": "Việt Nam chính thức gia nhập ASEAN vào ngày 28/7/1995"}, {"id": "4", "statement": "ASEAN là khối liên kết kinh tế có quy mô GDP lớn nhất thế giới"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": false}}$q$::jsonb, 'thong_hieu', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('05cf8315-8655-4904-a45f-87921a247afe', 'd5954a9e-8506-4f5b-b327-257fa6d9839d', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'essay', $q$Phân tích đặc điểm tự nhiên của khu vực Đông Nam Á và ảnh hưởng của chúng đến sự phát triển kinh tế - xã hội của khu vực.$q$, NULL, $q${"sample": "Đặc điểm tự nhiên khu vực Đông Nam Á:\n1. Khí hậu: Nhiệt đới ẩm gió mùa là chủ yếu, nóng ẩm quanh năm, lượng mưa lớn → Thuận lợi trồng lúa nước, cây công nghiệp nhiệt đới (cao su, cà phê, hồ tiêu).\n2. Sông ngòi: Nhiều sông lớn như Mekong, Irrawaddy, Chao Phraya → Cung cấp nước tưới, phù sa màu mỡ, phát triển thủy sản và giao thông đường thủy.\n3. Biển: Đường bờ biển dài, nhiều vũng vịnh → Thuận lợi phát triển cảng biển, đánh bắt thủy hải sản, du lịch biển đảo.\n4. Khoáng sản: Phong phú như dầu mỏ và khí đốt (Indonesia, Brunei, Malaysia), than đá, quặng thiếc, đồng → Thu hút đầu tư, xuất khẩu.\n5. Hạn chế: Địa hình phức tạp (bán đảo + hàng nghìn đảo) gây khó khăn cho giao thông liên kết nội vùng; Thiên tai như bão lũ, sóng thần thường xuyên.", "keywords": ["Đông Nam Á", "gió mùa", "Mekong", "dầu mỏ", "biển", "lúa nước", "cao su", "ASEAN", "thiên tai"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('1dadc940-e56f-4aa0-9aea-cd84055a1410', 'd5954a9e-8506-4f5b-b327-257fa6d9839d', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'essay', $q$So sánh quá trình phát triển kinh tế của Nhật Bản và Trung Quốc từ thế kỷ XX đến nay. Rút ra bài học kinh nghiệm phát triển cho Việt Nam.$q$, NULL, $q${"sample": "Nhật Bản:\n- Cải cách Minh Trị (1868): hiện đại hóa đất nước sớm, xây dựng nền công nghiệp.\n- Sau CTTG2 (1945): phục hồi thần kỳ nhờ viện trợ Mỹ, đầu tư công nghệ cao, giáo dục chất lượng cao, kỷ luật lao động. Đến thập niên 1980 trở thành nền kinh tế lớn thứ 2 thế giới.\n- Hiện nay: kinh tế lớn thứ 3, thách thức: già hóa dân số, thiếu tài nguyên.\nTrung Quốc:\n- Cải cách mở cửa từ năm 1978 (Đặng Tiểu Bình): thu hút FDI, phát triển khu kinh tế đặc biệt, kết hợp kinh tế thị trường với vai trò nhà nước.\n- Tăng trưởng GDP nhanh nhất lịch sử, trở thành nền kinh tế lớn thứ 2 thế giới.\n- Thách thức: bất bình đẳng giàu nghèo, môi trường, dân số già.\nBài học cho Việt Nam:\n- Đầu tư mạnh vào giáo dục và khoa học - công nghệ\n- Mở cửa thu hút đầu tư có chọn lọc, ưu tiên công nghệ cao\n- Phát triển bền vững, tránh bẫy thu nhập trung bình\n- Phát huy văn hóa truyền thống và tinh thần lao động cần cù", "keywords": ["Nhật Bản", "Trung Quốc", "Minh Trị", "cải cách mở cửa", "FDI", "công nghệ", "giáo dục", "Việt Nam", "bẫy thu nhập trung bình"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('5c42ae9a-82ab-41b9-a0b7-32d72de8f2b6', '4cefe059-d36f-427b-9b72-41e38b30103e', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Việt Nam có đường bờ biển chạy dài theo chiều Bắc - Nam với tổng chiều dài khoảng bao nhiêu km?$q$, $q$[{"id": "A", "text": "Khoảng 2.500 km"}, {"id": "B", "text": "Khoảng 3.260 km"}, {"id": "C", "text": "Khoảng 4.000 km"}, {"id": "D", "text": "Khoảng 5.000 km"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('fc095ba2-a1ee-492d-a16b-026e26d34bfc', '4cefe059-d36f-427b-9b72-41e38b30103e', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Vùng Đồng bằng sông Cửu Long trở thành vùng trọng điểm sản xuất lúa gạo và thủy sản của Việt Nam chủ yếu nhờ điều kiện tự nhiên nào?$q$, $q$[{"id": "A", "text": "Dân số đông nhất cả nước, nguồn lao động dồi dào"}, {"id": "B", "text": "Địa hình bằng phẳng, đất phù sa màu mỡ, khí hậu nhiệt đới nóng ẩm, nguồn nước từ sông Mekong dồi dào"}, {"id": "C", "text": "Gần các trung tâm công nghiệp và chế biến lớn của cả nước"}, {"id": "D", "text": "Lực lượng lao động có trình độ kỹ thuật và chuyên môn cao nhất"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('04f23d69-505e-4ffb-89ac-cdbc1df647ea', '4cefe059-d36f-427b-9b72-41e38b30103e', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Vùng Tây Nguyên có lợi thế đặc biệt trong việc phát triển những loại cây công nghiệp nào?$q$, $q$[{"id": "A", "text": "Lúa nước và mía đường"}, {"id": "B", "text": "Cà phê, hồ tiêu, cao su và chè"}, {"id": "C", "text": "Dừa và điều (đào lộn hột)"}, {"id": "D", "text": "Bông vải và đậu tương"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('e2c90673-9eb2-4554-80a5-3052dd52e635', '4cefe059-d36f-427b-9b72-41e38b30103e', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'multiple_choice', $q$Thách thức lớn nhất của vùng Đồng bằng sông Cửu Long trong bối cảnh biến đổi khí hậu là gì và cần có giải pháp phát triển bền vững nào?$q$, $q$[{"id": "A", "text": "Thiếu lao động và vốn đầu tư cho nông nghiệp hiện đại"}, {"id": "B", "text": "Nước biển dâng, xâm nhập mặn ngày càng sâu vào đất liền và tình trạng sụt lún đất → cần chuyển đổi mô hình sản xuất, phát triển nuôi trồng thủy sản thích ứng và du lịch sinh thái"}, {"id": "C", "text": "Ô nhiễm công nghiệp từ các khu công nghiệp mới xây dựng"}, {"id": "D", "text": "Thiếu quỹ đất canh tác do tốc độ đô thị hóa quá nhanh"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('2152c10c-e68a-445a-9e40-0555d950b81a', '4cefe059-d36f-427b-9b72-41e38b30103e', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu về địa lý tự nhiên Việt Nam:$q$, $q$[{"id": "1", "statement": "Lãnh thổ Việt Nam nằm ở phía Đông bán đảo Đông Dương, có hình chữ S kéo dài"}, {"id": "2", "statement": "Dãy Trường Sơn chạy dọc theo chiều Bắc - Nam là dãy núi dài và quan trọng nhất của Việt Nam"}, {"id": "3", "statement": "Sông Đà là phụ lưu lớn và quan trọng nhất của hệ thống sông Hồng"}, {"id": "4", "statement": "Vịnh Hạ Long đã hai lần được UNESCO công nhận là Di sản Thiên nhiên Thế giới"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('d3f2a396-206a-47a0-9394-5b3027a34455', '4cefe059-d36f-427b-9b72-41e38b30103e', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'true_false', $q$Nhận định về các vùng kinh tế của Việt Nam:$q$, $q$[{"id": "1", "statement": "Đồng bằng sông Hồng là vùng có mật độ dân số cao nhất trong cả nước"}, {"id": "2", "statement": "Vùng kinh tế trọng điểm phía Nam (TP. Hồ Chí Minh, Đồng Nai, Bình Dương...) có đóng góp GDP lớn nhất"}, {"id": "3", "statement": "Tây Nguyên là vùng có tỉ lệ che phủ rừng tự nhiên cao nhất cả nước hiện nay"}, {"id": "4", "statement": "Vùng Đông Nam Bộ tập trung nhiều khu công nghiệp và khu chế xuất nhất so với các vùng khác"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": false, "4": true}}$q$::jsonb, 'thong_hieu', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('020bc8da-5ae5-41d9-ba45-68c6e9afeed3', '4cefe059-d36f-427b-9b72-41e38b30103e', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'essay', $q$Phân tích thế mạnh và hạn chế của vùng Trung du và miền núi Bắc Bộ trong phát triển kinh tế - xã hội.$q$, NULL, $q${"sample": "Thế mạnh:\n1. Khoáng sản phong phú và đa dạng: than đá (Quảng Ninh - trữ lượng lớn nhất cả nước), apatit (Lào Cai), đồng (Lào Cai), sắt (Thái Nguyên), chì, kẽm... → Phát triển công nghiệp khai khoáng và chế biến.\n2. Tiềm năng thủy điện lớn: Hệ thống sông Đà, sông Lô, sông Gâm có trữ năng thủy điện lớn → Xây dựng các nhà máy thủy điện lớn như Hòa Bình, Sơn La, Lai Châu.\n3. Đất đai và khí hậu đa dạng: Phát triển chè (Thái Nguyên, Yên Bái), cây ăn quả ôn đới (mận, đào, lê), rừng cung cấp lâm sản.\n4. Du lịch sinh thái và văn hóa: Sa Pa, Hạ Long, Mộc Châu, Cao Bằng thu hút khách du lịch.\nHạn chế:\n1. Địa hình hiểm trở, bị chia cắt mạnh → Giao thông đi lại khó khăn, chi phí đầu tư hạ tầng cao.\n2. Dân cư thưa thớt, thiếu lao động có trình độ kỹ thuật.\n3. Còn nhiều hộ nghèo, đặc biệt ở vùng dân tộc thiểu số; khoảng cách phát triển lớn so với vùng đồng bằng.\n4. Thiên tai nhiều: lũ quét, sạt lở đất thường xuyên xảy ra vào mùa mưa.", "keywords": ["Trung du", "miền núi Bắc Bộ", "than Quảng Ninh", "thủy điện", "Hòa Bình", "Sơn La", "chè", "Sa Pa", "địa hình", "dân tộc thiểu số"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('ef29b404-c7f6-451d-bb4b-4316303c8fb4', '4cefe059-d36f-427b-9b72-41e38b30103e', '7991bd15-fd14-4eed-826d-b62b3463d30b', 'essay', $q$Phân tích nguyên nhân vùng Đông Nam Bộ trở thành vùng kinh tế phát triển nhất Việt Nam. Đề xuất các giải pháp để phát triển bền vững vùng này.$q$, NULL, $q${"sample": "Nguyên nhân phát triển:\n1. Vị trí địa lý chiến lược: Gần các tuyến hàng hải quốc tế, thuận tiện giao thương với các nước Đông Nam Á và thế giới.\n2. TP. Hồ Chí Minh là đầu mối giao thông, thương mại, tài chính lớn nhất cả nước; là đầu tàu kinh tế.\n3. Lực lượng lao động đông đảo, năng động, có trình độ và tinh thần kinh doanh.\n4. Hạ tầng kinh tế - xã hội được đầu tư sớm và đồng bộ (cảng Cát Lái, sân bay Tân Sơn Nhất...).\n5. Chính sách mở cửa thu hút đầu tư nước ngoài hiệu quả; nhiều khu công nghiệp, khu chế xuất (Bình Dương, Đồng Nai).\n6. Tài nguyên dầu khí trên thềm lục địa (mỏ Bạch Hổ, Rồng...).\nGiải pháp phát triển bền vững:\n- Phát triển công nghiệp công nghệ cao, kinh tế số, giảm dần công nghiệp gây ô nhiễm.\n- Giải quyết ô nhiễm môi trường (sông Đồng Nai, kênh rạch TP.HCM).\n- Xây dựng hạ tầng giao thông vùng: sân bay quốc tế Long Thành, các tuyến metro, đường vành đai.\n- Phát triển đô thị thông minh (smart city) tại TP.HCM.", "keywords": ["Đông Nam Bộ", "TP.HCM", "cảng", "FDI", "khu công nghiệp", "dầu khí", "Long Thành", "metro", "đô thị thông minh", "bền vững"]}$q$::jsonb, 'van_dung', TRUE, '5d46e056-4908-493c-9af8-1d67944b152b', NOW()),
('83e66ae4-f466-45b1-876e-2de3276e9ee0', 'a63e772a-39f3-4c64-9355-6295261006dc', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Triết học được hiểu là gì?$q$, $q$[{"id": "A", "text": "Khoa học chuyên nghiên cứu các hiện tượng tự nhiên và vũ trụ"}, {"id": "B", "text": "Hệ thống các quan điểm lý luận chung nhất về thế giới và về vị trí, vai trò của con người trong thế giới đó"}, {"id": "C", "text": "Khoa học nghiên cứu về đạo đức, hành vi và chuẩn mực xã hội"}, {"id": "D", "text": "Bộ môn nghiên cứu lịch sử phát triển của tư tưởng nhân loại"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('2cbf1a6e-5bfc-465e-b70a-4bf3beef51ca', 'a63e772a-39f3-4c64-9355-6295261006dc', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Vấn đề cơ bản của triết học bao gồm hai mặt là gì?$q$, $q$[{"id": "A", "text": "Mối quan hệ giữa vật chất và ý thức; và mối quan hệ nhân - quả trong thế giới"}, {"id": "B", "text": "Mối quan hệ giữa vật chất và ý thức (bản thể luận); và khả năng con người có nhận thức được thế giới không (nhận thức luận)"}, {"id": "C", "text": "Mối quan hệ giữa tự nhiên và xã hội; và mối quan hệ giữa lý luận và thực tiễn"}, {"id": "D", "text": "Mối quan hệ giữa tồn tại và tư duy; và mối quan hệ giữa khả năng và hiện thực"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('a4371700-6b82-4c89-9fe3-19a0799456d8', 'a63e772a-39f3-4c64-9355-6295261006dc', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Hành vi nào sau đây thể hiện thế giới quan duy vật biện chứng?$q$, $q$[{"id": "A", "text": "Tin rằng số phận và vận mệnh của mỗi người đã được ông trời định sẵn từ trước"}, {"id": "B", "text": "Cho rằng vật chất có trước và quyết định ý thức; phải xuất phát từ thực tế khách quan để hành động"}, {"id": "C", "text": "Tin vào các lực lượng siêu nhiên như phép thuật, bùa chú, bói toán"}, {"id": "D", "text": "Cho rằng ý thức, tư tưởng của con người tạo ra và quyết định thế giới vật chất"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('a72486ee-9d92-4d4a-a0b9-261834b1a320', 'a63e772a-39f3-4c64-9355-6295261006dc', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Bạn Minh phát hiện bạn cùng lớp Tuấn gian lận trong kỳ thi học kỳ. Hành động nào sau đây thể hiện quan điểm đạo đức đúng đắn nhất theo triết học duy vật biện chứng?$q$, $q$[{"id": "A", "text": "Bỏ qua, làm ngơ vì đây không phải chuyện liên quan đến bản thân mình"}, {"id": "B", "text": "Phân tích hậu quả của hành vi gian lận, khuyên Tuấn thành thật và nếu cần thiết thì báo cáo giáo viên để bảo vệ sự công bằng"}, {"id": "C", "text": "Ngay lập tức tố cáo với giáo viên mà không cần suy nghĩ hay lắng nghe giải thích"}, {"id": "D", "text": "Làm theo Tuấn vì trong hoàn cảnh áp lực học tập, ai cũng có thể làm vậy"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('034acff3-9387-4da0-b596-d6909304f9f6', 'a63e772a-39f3-4c64-9355-6295261006dc', '266b777b-cb00-471b-a578-d7f78ce16017', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu về phép biện chứng duy vật:$q$, $q$[{"id": "1", "statement": "Mọi sự vật, hiện tượng trong thế giới đều luôn vận động, biến đổi và phát triển không ngừng"}, {"id": "2", "statement": "Mâu thuẫn bên trong sự vật là nguồn gốc và động lực của sự vận động, phát triển"}, {"id": "3", "statement": "Sự thay đổi dần dần về lượng không bao giờ dẫn đến sự thay đổi nhảy vọt về chất"}, {"id": "4", "statement": "Phủ định biện chứng là phủ định có tính kế thừa - giữ lại những yếu tố tích cực của cái cũ"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": false, "4": true}}$q$::jsonb, 'thong_hieu', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('c2c04fd0-b04b-4852-871c-1e4c9469c7d9', 'a63e772a-39f3-4c64-9355-6295261006dc', '266b777b-cb00-471b-a578-d7f78ce16017', 'true_false', $q$Phân tích các phát biểu sau về nhận thức và thực tiễn:$q$, $q$[{"id": "1", "statement": "Thực tiễn (lao động sản xuất, đấu tranh xã hội, thực nghiệm khoa học) là cơ sở, nguồn gốc của nhận thức"}, {"id": "2", "statement": "Nhận thức cảm tính (cảm giác, tri giác, biểu tượng) là giai đoạn nhận thức cao hơn nhận thức lý tính"}, {"id": "3", "statement": "Chân lý là những tri thức phản ánh đúng đắn, chính xác hiện thực khách quan và được thực tiễn kiểm nghiệm"}, {"id": "4", "statement": "Thực tiễn là tiêu chuẩn khách quan duy nhất để kiểm tra tính đúng đắn của nhận thức"}]$q$::jsonb, $q${"answers": {"1": true, "2": false, "3": true, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('e62af249-b836-442b-919c-1af2d3ff8e1a', 'a63e772a-39f3-4c64-9355-6295261006dc', '266b777b-cb00-471b-a578-d7f78ce16017', 'essay', $q$Trình bày quan điểm của chủ nghĩa duy vật biện chứng về mối quan hệ giữa vật chất và ý thức. Phân tích ý nghĩa thực tiễn của quan điểm này.$q$, NULL, $q${"sample": "Quan điểm duy vật biện chứng về mối quan hệ vật chất - ý thức:\n1. Vật chất có trước, ý thức có sau: Thế giới vật chất tồn tại khách quan, độc lập với ý thức con người. Ý thức chỉ là sự phản ánh thế giới vật chất vào bộ óc con người thông qua hoạt động thực tiễn.\n2. Vật chất quyết định ý thức: Điều kiện vật chất (kinh tế, môi trường sống...) quyết định tư tưởng, ý thức. 'Tồn tại xã hội quyết định ý thức xã hội' (Marx).\n3. Ý thức có tính năng động, tích cực: Tuy do vật chất quyết định nhưng ý thức có thể tác động mạnh mẽ trở lại vật chất thông qua hoạt động thực tiễn của con người. Ý thức đúng đắn thúc đẩy sự phát triển; ý thức sai lầm cản trở sự phát triển.\nÝ nghĩa thực tiễn:\n- Phải xuất phát từ thực tế khách quan, tôn trọng và hành động theo quy luật khách quan, không được duy tâm, chủ quan, ý chí.\n- Đồng thời phải phát huy tính tích cực, sáng tạo của ý thức, ý chí con người trong cải tạo tự nhiên và xã hội.", "keywords": ["vật chất", "ý thức", "duy vật", "biện chứng", "khách quan", "thực tiễn", "phản ánh", "Marx", "tồn tại xã hội", "quyết định"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('262a28ec-cd42-4062-9aa9-18ff3a69454f', 'a63e772a-39f3-4c64-9355-6295261006dc', '266b777b-cb00-471b-a578-d7f78ce16017', 'essay', $q$Phân tích nguyên lý về sự phát triển trong phép biện chứng duy vật. Vận dụng nguyên lý này vào việc học tập và rèn luyện của bản thân học sinh.$q$, NULL, $q${"sample": "Nội dung nguyên lý về sự phát triển:\n1. Phát triển là xu hướng vận động chung của mọi sự vật, hiện tượng theo chiều hướng đi lên từ thấp đến cao, từ đơn giản đến phức tạp, từ kém hoàn thiện đến hoàn thiện hơn.\n2. Phát triển là quá trình biến đổi về chất, không phải chỉ là sự tăng lên về lượng.\n3. Nguồn gốc của sự phát triển là mâu thuẫn bên trong sự vật và việc giải quyết mâu thuẫn đó.\n4. Phát triển theo hình xoáy ốc: phủ định của phủ định - cái mới ra đời trên cơ sở kế thừa cái cũ.\nVận dụng trong học tập:\n- Học tập là quá trình tích lũy kiến thức dần dần, không thể nóng vội; cần kiên trì, nhẫn nại.\n- Khó khăn, thất bại trong học tập là mâu thuẫn cần giải quyết, là động lực để tiến bộ.\n- Phải không ngừng đổi mới phương pháp học, tiếp thu cái mới trong khi kế thừa kiến thức đã có.\n- Mỗi bước tiến trong học tập là sự tích lũy về lượng để tạo nên bước nhảy về chất (ví dụ: học đủ, hiểu sâu thì làm bài tốt).", "keywords": ["phát triển", "biện chứng", "vận động", "mâu thuẫn", "phủ định", "kế thừa", "hình xoáy ốc", "lượng", "chất", "học tập"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('2275ac3a-a791-4398-a950-5312f642a2ab', '234b30b1-e0ca-48de-a772-2b1d2bdda973', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Theo Hiến pháp năm 2013, Nhà nước Cộng hòa Xã hội Chủ nghĩa Việt Nam là nhà nước của ai, do ai và vì ai?$q$, $q$[{"id": "A", "text": "Nhà nước của giai cấp công nhân và nông dân"}, {"id": "B", "text": "Nhà nước của nhân dân, do nhân dân làm chủ và vì lợi ích của nhân dân"}, {"id": "C", "text": "Nhà nước của Đảng Cộng sản Việt Nam lãnh đạo"}, {"id": "D", "text": "Nhà nước của liên minh giai cấp công nhân, nông dân và trí thức"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('6d254876-313a-437d-8f0e-a0db8d4242af', '234b30b1-e0ca-48de-a772-2b1d2bdda973', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Pháp luật khác với các quy phạm đạo đức ở điểm cơ bản nhất là gì?$q$, $q$[{"id": "A", "text": "Pháp luật do Nhà nước ban hành và được đảm bảo thực hiện bằng quyền lực nhà nước"}, {"id": "B", "text": "Pháp luật xuất hiện trước khi đạo đức hình thành trong xã hội"}, {"id": "C", "text": "Đạo đức không có giá trị điều chỉnh hành vi con người trong xã hội hiện đại"}, {"id": "D", "text": "Pháp luật chỉ điều chỉnh các quan hệ kinh tế và tài sản"}]$q$::jsonb, $q${"selected": ["A"]}$q$::jsonb, 'thong_hieu', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('3fa6d071-69a6-4f28-ad40-612dd80d6ec4', '234b30b1-e0ca-48de-a772-2b1d2bdda973', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Theo quy định của pháp luật Việt Nam hiện hành, công dân có quyền bầu cử đại biểu Quốc hội và đại biểu HĐND khi đủ bao nhiêu tuổi?$q$, $q$[{"id": "A", "text": "Đủ 16 tuổi trở lên"}, {"id": "B", "text": "Đủ 18 tuổi trở lên"}, {"id": "C", "text": "Đủ 21 tuổi trở lên"}, {"id": "D", "text": "Đủ 20 tuổi trở lên"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('3acb15da-53a7-4d15-9dcb-bd093c00dd2f', '234b30b1-e0ca-48de-a772-2b1d2bdda973', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Công ty TNHH Đại Dương xả thải nước độc hại ra sông gây ô nhiễm nghiêm trọng. Phân tích trách nhiệm pháp lý mà công ty này phải chịu?$q$, $q$[{"id": "A", "text": "Chỉ phải chịu trách nhiệm dân sự bồi thường thiệt hại cho người bị ảnh hưởng"}, {"id": "B", "text": "Có thể bị xử phạt vi phạm hành chính, bồi thường dân sự và truy cứu trách nhiệm hình sự tùy thuộc vào mức độ vi phạm"}, {"id": "C", "text": "Chỉ bị phạt hành chính với mức tiền phạt tối đa theo quy định"}, {"id": "D", "text": "Không phải chịu trách nhiệm nếu đã có đầy đủ giấy phép kinh doanh"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('358044e7-bc2d-4804-8f02-d17265a11900', '234b30b1-e0ca-48de-a772-2b1d2bdda973', '266b777b-cb00-471b-a578-d7f78ce16017', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu về hệ thống chính trị của Nhà nước Việt Nam:$q$, $q$[{"id": "1", "statement": "Quốc hội là cơ quan đại biểu cao nhất của nhân dân, cơ quan quyền lực nhà nước cao nhất của nước CHXHCN Việt Nam"}, {"id": "2", "statement": "Chủ tịch nước do Quốc hội bầu ra trong số các đại biểu Quốc hội và chịu trách nhiệm trước Quốc hội"}, {"id": "3", "statement": "Hội đồng nhân dân cấp tỉnh là cơ quan hành chính nhà nước cao nhất ở địa phương"}, {"id": "4", "statement": "Viện Kiểm sát nhân dân có chức năng thực hành quyền công tố và kiểm sát hoạt động tư pháp"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": false, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('1e477c69-fb27-458b-b35a-80c3649509f4', '234b30b1-e0ca-48de-a772-2b1d2bdda973', '266b777b-cb00-471b-a578-d7f78ce16017', 'true_false', $q$Phân tích các nhận định về quyền và nghĩa vụ cơ bản của công dân Việt Nam:$q$, $q$[{"id": "1", "statement": "Quyền công dân và nghĩa vụ công dân không thể tách rời nhau, thực hiện quyền phải đi đôi với thực hiện nghĩa vụ"}, {"id": "2", "statement": "Công dân Việt Nam đủ 21 tuổi có quyền ứng cử đại biểu Quốc hội"}, {"id": "3", "statement": "Mọi công dân Việt Nam đều có nghĩa vụ nộp thuế đầy đủ và đúng hạn theo quy định pháp luật"}, {"id": "4", "statement": "Người nước ngoài đang sinh sống và làm việc tại Việt Nam không có bất kỳ quyền và nghĩa vụ pháp lý nào"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": true, "4": false}}$q$::jsonb, 'thong_hieu', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('fbdb1a5d-a603-4ec1-b233-a1cf945a8858', '234b30b1-e0ca-48de-a772-2b1d2bdda973', '266b777b-cb00-471b-a578-d7f78ce16017', 'essay', $q$Phân tích vai trò của pháp luật trong đời sống xã hội. Liên hệ trách nhiệm của học sinh THPT trong việc tìm hiểu và chấp hành pháp luật.$q$, NULL, $q${"sample": "Vai trò của pháp luật trong đời sống xã hội:\n1. Công cụ quản lý xã hội của Nhà nước: Pháp luật điều chỉnh các quan hệ xã hội, tạo ra trật tự và kỷ cương trong xã hội.\n2. Bảo vệ quyền và lợi ích hợp pháp của công dân: Pháp luật quy định các quyền cơ bản (quyền sống, quyền tự do, quyền sở hữu tài sản...) và cơ chế bảo vệ các quyền đó.\n3. Đảm bảo an toàn và trật tự xã hội: Xử lý các hành vi vi phạm, bảo vệ an ninh quốc gia và trật tự công cộng.\n4. Phương tiện thực hiện dân chủ: Pháp luật đảm bảo quyền tham gia của công dân vào quản lý nhà nước và xã hội.\n5. Điều chỉnh các quan hệ kinh tế: Tạo môi trường pháp lý công bằng cho sản xuất kinh doanh.\nLiên hệ trách nhiệm học sinh:\n- Tìm hiểu và nắm vững các quy định pháp luật liên quan đến lứa tuổi (Luật Giao thông đường bộ, Luật Trẻ em, Luật Phòng chống ma túy...)\n- Chấp hành nghiêm túc: không vi phạm an toàn giao thông, không sử dụng chất kích thích\n- Tôn trọng quyền và lợi ích hợp pháp của người khác\n- Tích cực phát hiện và phản ánh các hành vi vi phạm pháp luật", "keywords": ["pháp luật", "vai trò", "Nhà nước", "quyền công dân", "trật tự", "dân chủ", "học sinh", "chấp hành", "an toàn giao thông"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('de7e70e2-588f-49c8-bde5-4482f5a99686', '234b30b1-e0ca-48de-a772-2b1d2bdda973', '266b777b-cb00-471b-a578-d7f78ce16017', 'essay', $q$Phân biệt bốn hình thức thực hiện pháp luật: tuân thủ, thi hành, sử dụng và áp dụng pháp luật. Cho ví dụ cụ thể minh họa.$q$, NULL, $q${"sample": "Bốn hình thức thực hiện pháp luật:\n1. Tuân thủ pháp luật: Chủ thể kiềm chế, không thực hiện những hành vi mà pháp luật cấm (nghĩa vụ thụ động).\n   Ví dụ: Không lái xe khi đã uống rượu bia; không trộm cắp, không gây rối trật tự công cộng.\n2. Thi hành pháp luật: Chủ thể chủ động thực hiện những hành vi mà pháp luật bắt buộc phải làm (nghĩa vụ tích cực).\n   Ví dụ: Thanh niên đến tuổi phải đăng ký nghĩa vụ quân sự; công dân nộp thuế thu nhập cá nhân đúng hạn.\n3. Sử dụng pháp luật: Chủ thể thực hiện những quyền mà pháp luật cho phép, tùy thuộc vào ý chí của mình.\n   Ví dụ: Công dân thực hiện quyền khiếu nại, tố cáo; quyền ly hôn; quyền bầu cử.\n4. Áp dụng pháp luật: Cơ quan, tổ chức, cá nhân có thẩm quyền căn cứ vào pháp luật để ra quyết định làm phát sinh, thay đổi, chấm dứt các quan hệ pháp luật.\n   Ví dụ: Tòa án tuyên bản án hình sự; UBND xã cấp giấy chứng nhận kết hôn; Cảnh sát giao thông xử phạt vi phạm.", "keywords": ["tuân thủ", "thi hành", "sử dụng", "áp dụng", "pháp luật", "cơ quan", "thẩm quyền", "nghĩa vụ", "quyền", "ví dụ"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('0d3d0403-9495-457b-ad8b-34f15f713c9d', '5645dbcc-cdce-49f6-9b21-7cccd4d3a409', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Quyền bình đẳng của công dân trước pháp luật được hiểu theo nghĩa nào sau đây?$q$, $q$[{"id": "A", "text": "Mọi người đều có mức thu nhập và điều kiện sống như nhau"}, {"id": "B", "text": "Mọi công dân đều bình đẳng về quyền và nghĩa vụ pháp lý, được đối xử như nhau trước pháp luật và cơ quan tư pháp"}, {"id": "C", "text": "Không có sự phân biệt đối xử giữa người dân các vùng miền khác nhau"}, {"id": "D", "text": "Mọi công dân đều được hưởng mức lương tối thiểu như nhau"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'nhan_biet', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('ad0b5595-5352-43e9-9ce9-f40677136def', '5645dbcc-cdce-49f6-9b21-7cccd4d3a409', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Quyền tham gia quản lý nhà nước và xã hội của công dân được thực hiện thông qua những hình thức nào?$q$, $q$[{"id": "A", "text": "Chỉ thông qua việc bầu cử đại biểu Quốc hội theo định kỳ"}, {"id": "B", "text": "Thông qua dân chủ trực tiếp (trưng cầu dân ý, họp dân, kiến nghị) và dân chủ đại diện (bầu cử, bãi miễn đại biểu)"}, {"id": "C", "text": "Chỉ thông qua hoạt động của các tổ chức chính trị - xã hội như Mặt trận Tổ quốc, Công đoàn"}, {"id": "D", "text": "Công dân bình thường không có cách nào tham gia trực tiếp vào quản lý nhà nước"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'thong_hieu', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('9ac1ff74-fdf3-4587-9b35-5aef409a6592', '5645dbcc-cdce-49f6-9b21-7cccd4d3a409', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Hành vi nào sau đây xâm phạm quyền được pháp luật bảo hộ về danh dự và nhân phẩm của công dân?$q$, $q$[{"id": "A", "text": "Phê bình, nhắc nhở bạn học sinh vi phạm nội quy nhà trường trong buổi họp lớp"}, {"id": "B", "text": "Đăng tải thông tin bịa đặt, sai sự thật về một người lên mạng xã hội gây ảnh hưởng xấu đến uy tín"}, {"id": "C", "text": "Tố cáo với cơ quan công an hành vi vi phạm pháp luật của người khác"}, {"id": "D", "text": "Phản ánh những sai phạm trong cơ quan, đơn vị lên cơ quan có thẩm quyền cấp trên"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('9446da11-37bf-4e17-9b99-ebbc601ddb5b', '5645dbcc-cdce-49f6-9b21-7cccd4d3a409', '266b777b-cb00-471b-a578-d7f78ce16017', 'multiple_choice', $q$Anh Hùng bị cơ quan công an bắt tạm giam vì bị tình nghi thực hiện hành vi phạm tội, nhưng chưa có bản án của tòa án. Quyền nào của anh Hùng cần được đảm bảo và cơ quan nào có trách nhiệm?$q$, $q$[{"id": "A", "text": "Anh Hùng không còn quyền gì vì đang bị tạm giam theo lệnh của cơ quan công an"}, {"id": "B", "text": "Anh Hùng có quyền được coi là vô tội cho đến khi tòa án tuyên có tội; Viện Kiểm sát nhân dân giám sát việc tạm giam, Tòa án xét xử công bằng"}, {"id": "C", "text": "Anh Hùng chỉ còn duy nhất quyền im lặng, không cung cấp thông tin"}, {"id": "D", "text": "Toàn bộ các quyền dân sự và chính trị của anh Hùng bị tước đoạt ngay khi bị bắt"}]$q$::jsonb, $q${"selected": ["B"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('58c2b326-73c5-4159-8aa9-81702f6ab998', '5645dbcc-cdce-49f6-9b21-7cccd4d3a409', '266b777b-cb00-471b-a578-d7f78ce16017', 'true_false', $q$Xác định ĐÚNG hoặc SAI với các phát biểu về các quyền tự do cơ bản của công dân theo Hiến pháp 2013:$q$, $q$[{"id": "1", "statement": "Quyền bất khả xâm phạm về thân thể có nghĩa là không ai bị bắt nếu không có lệnh bắt của cơ quan điều tra, Viện kiểm sát hoặc Tòa án có thẩm quyền"}, {"id": "2", "statement": "Công dân có quyền tự do ngôn luận, tự do báo chí nhưng không được lợi dụng các quyền này để xâm phạm lợi ích của Nhà nước và xã hội"}, {"id": "3", "statement": "Quyền bí mật thư tín, điện thoại của công dân có thể bị hạn chế theo quyết định của bất kỳ cơ quan nhà nước nào"}, {"id": "4", "statement": "Mọi công dân Việt Nam đều có quyền tự do tín ngưỡng, tôn giáo; có thể theo hoặc không theo một tôn giáo nào"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": false, "4": true}}$q$::jsonb, 'nhan_biet', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('106db5ee-ce16-4c5d-b5f8-766e81c374a2', '5645dbcc-cdce-49f6-9b21-7cccd4d3a409', '266b777b-cb00-471b-a578-d7f78ce16017', 'true_false', $q$Phân tích các nhận định về các loại vi phạm pháp luật và trách nhiệm pháp lý:$q$, $q$[{"id": "1", "statement": "Trong bốn loại trách nhiệm pháp lý, trách nhiệm hình sự là nghiêm khắc nhất và do Tòa án áp dụng"}, {"id": "2", "statement": "Người từ đủ 14 tuổi đến dưới 16 tuổi chỉ phải chịu trách nhiệm hình sự về tội phạm rất nghiêm trọng và đặc biệt nghiêm trọng"}, {"id": "3", "statement": "Vi phạm hành chính là hành vi có mức độ nguy hiểm cho xã hội tương đương với tội phạm hình sự"}, {"id": "4", "statement": "Trách nhiệm dân sự (bồi thường thiệt hại) phát sinh khi một người có hành vi vi phạm pháp luật gây thiệt hại cho người khác"}]$q$::jsonb, $q${"answers": {"1": true, "2": true, "3": false, "4": true}}$q$::jsonb, 'thong_hieu', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('12328bed-dce5-4f42-8d67-72f09d18b0ae', '5645dbcc-cdce-49f6-9b21-7cccd4d3a409', '266b777b-cb00-471b-a578-d7f78ce16017', 'essay', $q$Phân tích nội dung quyền bình đẳng trong hôn nhân và gia đình theo pháp luật Việt Nam. Liên hệ với thực tiễn và trách nhiệm của thế hệ trẻ.$q$, NULL, $q${"sample": "Nội dung quyền bình đẳng trong hôn nhân và gia đình:\n1. Trong kết hôn: Việc kết hôn phải dựa trên nguyên tắc tự nguyện, tiến bộ, một vợ một chồng. Độ tuổi kết hôn: nam đủ 20 tuổi, nữ đủ 18 tuổi. Cấm kết hôn giữa những người có cùng dòng máu trực hệ hoặc trong phạm vi 3 đời.\n2. Giữa vợ và chồng: Bình đẳng về quyền và nghĩa vụ trong gia đình (tài sản chung, nuôi dạy con, quyết định các vấn đề gia đình). Không ai được phép ngược đãi, hành hạ hoặc xúc phạm danh dự của người kia.\n3. Giữa cha mẹ và con cái: Cha mẹ có nghĩa vụ nuôi dưỡng, chăm sóc, giáo dục con đến khi trưởng thành. Không phân biệt con trai - gái, con trong giá thú - ngoài giá thú. Con cái có bổn phận kính trọng, chăm sóc cha mẹ khi già yếu.\nThực tiễn và trách nhiệm thế hệ trẻ:\n- Vẫn còn tình trạng tảo hôn, hôn nhân cận huyết ở một số vùng dân tộc thiểu số.\n- Bạo lực gia đình vẫn là vấn đề nhức nhối.\n- Thế hệ trẻ cần: tìm hiểu Luật Hôn nhân và Gia đình; lên án bạo lực gia đình, tảo hôn; xây dựng gia đình bình đẳng, tiến bộ, hạnh phúc.", "keywords": ["bình đẳng", "hôn nhân", "gia đình", "tự nguyện", "tảo hôn", "bạo lực gia đình", "Luật Hôn nhân", "vợ chồng", "con cái", "trách nhiệm"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW()),
('b0993bdf-9250-4ec8-8448-a585d11c52c4', '5645dbcc-cdce-49f6-9b21-7cccd4d3a409', '266b777b-cb00-471b-a578-d7f78ce16017', 'essay', $q$Phân tích nội dung quyền được đảm bảo an toàn và bí mật thư tín, điện thoại, điện tín của công dân. Phân tích thực trạng và đề xuất giải pháp bảo vệ quyền này trong thời đại số.$q$, NULL, $q${"sample": "Nội dung quyền:\nTheo Điều 21 Hiến pháp 2013 và các luật liên quan, thư tín, điện thoại, điện tín và các hình thức trao đổi thông tin riêng tư khác của công dân được đảm bảo an toàn và bí mật. Chỉ trong trường hợp luật định và phải có quyết định của cơ quan có thẩm quyền (Tòa án, Viện Kiểm sát) mới được kiểm tra, kiểm soát. Mọi hành vi vi phạm đều bị xử lý nghiêm theo pháp luật.\nThực trạng trong thời đại số:\n- Hành vi xâm phạm ngày càng tinh vi: hack tài khoản mạng xã hội, email; nghe lén điện thoại; mua bán dữ liệu cá nhân; cài spyware, phần mềm gián điệp.\n- Lừa đảo qua điện thoại (giả danh công an, ngân hàng) gây thiệt hại lớn.\n- Nhiều người dùng vô tình để lộ thông tin cá nhân trên mạng xã hội.\nGiải pháp:\n1. Hoàn thiện pháp luật: Luật An ninh mạng 2018 và các nghị định hướng dẫn cần được thực thi nghiêm túc.\n2. Nâng cao ý thức người dùng: Giáo dục kỹ năng an toàn thông tin từ cấp học phổ thông.\n3. Xử lý nghiêm khắc các hành vi vi phạm để răn đe.\n4. Doanh nghiệp công nghệ phải có trách nhiệm bảo vệ dữ liệu người dùng.", "keywords": ["bí mật", "thư tín", "điện thoại", "Hiến pháp 2013", "an ninh mạng", "hack", "spyware", "dữ liệu cá nhân", "Luật An ninh mạng", "bảo vệ"]}$q$::jsonb, 'van_dung', TRUE, '1ca6e528-fbd1-4ac3-a418-eb5c39dfc54b', NOW());
